const supersedeAgentTaskRuntimeStartAttemptForLease = `-- name: SupersedeAgentTaskRuntimeStartAttemptForLease :one
WITH lease_owner AS MATERIALIZED (
    SELECT task.id
    FROM agent_task_queue AS task
    WHERE task.id = $1
      AND task.runtime_id = $2
      AND task.status IN ('queued', 'dispatched', 'running', 'waiting_local_directory')
      AND task.runtime_launch_lease_token = $3
      AND task.runtime_launch_lease_expires_at > now()
    FOR UPDATE
), superseded AS (
    UPDATE agent_task_runtime_start_attempt AS attempt
    SET status = 'superseded',
        last_stage = 'launch_restarted',
        error_code = 'START-ATTEMPT-SUPERSEDED',
        error_detail = 'superseded by a launcher holding a newer task lease',
        finished_at = now(),
        updated_at = now()
    WHERE attempt.task_id = $1
      AND attempt.runtime_id = $2
      AND attempt.status = 'starting'
      AND EXISTS (SELECT 1 FROM lease_owner)
    RETURNING attempt.id
)
SELECT EXISTS (SELECT 1 FROM lease_owner) AS lease_valid,
       count(*)::bigint AS superseded_count
FROM superseded
`

type SupersedeAgentTaskRuntimeStartAttemptForLeaseParams struct {
	TaskID     pgtype.UUID `json:"task_id"`
	RuntimeID  pgtype.UUID `json:"runtime_id"`
	LeaseToken pgtype.UUID `json:"lease_token"`
}

type SupersedeAgentTaskRuntimeStartAttemptForLeaseRow struct {
	LeaseValid      bool  `json:"lease_valid"`
	SupersededCount int64 `json:"superseded_count"`
}

// A launcher may be restarted after its 90-second task lease expires. Fence
// replacement with the newly acquired lease token, preserve the abandoned
// attempt as evidence, and keep the task -> attempt lock order used by claim
// and failure finalization.
func (q *Queries) SupersedeAgentTaskRuntimeStartAttemptForLease(ctx context.Context, arg SupersedeAgentTaskRuntimeStartAttemptForLeaseParams) (SupersedeAgentTaskRuntimeStartAttemptForLeaseRow, error) {
	row := q.db.QueryRow(ctx, supersedeAgentTaskRuntimeStartAttemptForLease, arg.TaskID, arg.RuntimeID, arg.LeaseToken)
	var i SupersedeAgentTaskRuntimeStartAttemptForLeaseRow
	err := row.Scan(&i.LeaseValid, &i.SupersededCount)
	return i, err
}

const supersedeAgentTaskRuntimeStartAttemptForTerminalTask = `-- name: SupersedeAgentTaskRuntimeStartAttemptForTerminalTask :execrows
UPDATE agent_task_runtime_start_attempt AS attempt
SET status = 'superseded',
    last_stage = 'task_terminal_before_capacity_wait',
    error_code = 'TASK-TERMINAL-BEFORE-CAPACITY-WAIT',
    error_detail = 'task became terminal before ASB capacity wait was recorded',
    finished_at = now(),
    updated_at = now()
WHERE attempt.id = $1
  AND attempt.task_id = $2
  AND attempt.runtime_id = $3
  AND attempt.status = 'starting'
  AND EXISTS (
      SELECT 1
      FROM agent_task_queue AS task
      WHERE task.id = attempt.task_id
        AND task.runtime_id = attempt.runtime_id
        AND task.status IN ('completed', 'failed', 'cancelled')
  )
`

type SupersedeAgentTaskRuntimeStartAttemptForTerminalTaskParams struct {
	ID        pgtype.UUID `json:"id"`
	TaskID    pgtype.UUID `json:"task_id"`
	RuntimeID pgtype.UUID `json:"runtime_id"`
}

// A cancellation can win the task row lock while the launcher is converting a
// capacity error into a blocked attempt. Close that observability record only
// when the task is already terminal; a concurrent claim keeps ownership of the
// normal claim finalizer.
func (q *Queries) SupersedeAgentTaskRuntimeStartAttemptForTerminalTask(ctx context.Context, arg SupersedeAgentTaskRuntimeStartAttemptForTerminalTaskParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeAgentTaskRuntimeStartAttemptForTerminalTask, arg.ID, arg.TaskID, arg.RuntimeID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

